const cfg = $('Configuration').first().json;
const session = $input.first().json;
const searches = [
  { category: 'n8n automation', keyword: 'n8n automation' },
  { category: 'web scraping and data extraction', keyword: 'web scraping' },
];

return searches.map((search) => ({
  json: {
    ...cfg,
    ...search,
    sessionId: session.sessionId,
    search_url: `https://www.onlinejobs.ph/jobseekers/jobsearch?jobkeyword=${encodeURIComponent(search.keyword)}`,
  },
}));

function parseJson(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string') return [];
  const clean = value.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(clean); } catch {}
  const start = clean.indexOf('[');
  const end = clean.lastIndexOf(']');
  if (start >= 0 && end > start) {
    try { return JSON.parse(clean.slice(start, end + 1)); } catch {}
  }
  return [];
}

const inputs = $input.all();
const searches = $('Search Categories').all();
const output = [];

for (let i = 0; i < inputs.length; i++) {
  const raw = inputs[i].json;
  const source = searches[i]?.json || {};
  const modelResponse = raw?.data?.modelResponse ?? raw?.modelResponse ?? raw?.data?.result ?? raw?.result ?? raw;
  const parsed = parseJson(modelResponse);
  const rows = Array.isArray(parsed) ? parsed : (Array.isArray(parsed?.jobs) ? parsed.jobs : []);
  const sessionId = raw.sessionId ?? raw?.data?.sessionId ?? '';

  for (const row of rows.slice(0, Number(source.max_results_per_category || 5))) {
    let url = String(row.url || '').trim();
    if (url.startsWith('/')) url = `https://www.onlinejobs.ph${url}`;
    if (!/^https:\/\/(?:www\.)?onlinejobs\.ph\/jobseekers\/job\//i.test(url)) continue;
    const roleText = `${row.title || ''} ${row.snippet || ''}`.toLowerCase();
    const isAiVideoRole = /(ai[- ]?video|video editor|video editing|youtube automation|faceless[- ]?video|script[- ]?to[- ]?video|video content creator)/i.test(roleText);
    if (isAiVideoRole) continue;
    output.push({
      json: {
        kind: 'candidate',
        category: source.category,
        keyword: source.keyword,
        url,
        search_title: row.title || '',
        search_employer: row.employer || '',
        search_date: row.posted_or_updated_text || '',
        search_work_type: row.work_type || '',
        search_salary: row.salary || '',
        search_snippet: row.snippet || '',
        search_session_id: sessionId,
      },
    });
  }
}

const seen = new Set();
const unique = output.filter((item) => {
  const key = item.json.url.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return unique.length ? unique : [{ json: { kind: 'none', reason: 'No direct n8n-automation or web-scraping job links were extracted from the current live search results.' } }];

function parseJson(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string') return null;
  const clean = value.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(clean); } catch {}
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try { return JSON.parse(clean.slice(start, end + 1)); } catch {}
  }
  return null;
}

function ageInDays(text) {
  const value = String(text || '').trim();
  if (!value) return null;
  if (/\btoday\b/i.test(value)) return 0;
  if (/\byesterday\b/i.test(value)) return 1;
  const match = value.match(/(\d+)\s*(?:day|days)\s*ago/i);
  if (match) return Number(match[1]);
  const parsed = Date.parse(value);
  if (!Number.isFinite(parsed)) return null;
  return (Date.now() - parsed) / 86400000;
}

const details = $input.all();
const candidates = $('Parse Search Results').all();
const valid = [];

for (let i = 0; i < details.length; i++) {
  const raw = details[i].json;
  const candidate = candidates[i]?.json || {};
  const modelResponse = raw?.data?.modelResponse ?? raw?.modelResponse ?? raw?.data?.result ?? raw?.result ?? raw;
  const job = parseJson(modelResponse);
  if (!job) continue;

  const url = String(candidate.url || '');
  const active = String(job.active_status || '').toLowerCase() === 'active';
  const direct = /^https:\/\/(?:www\.)?onlinejobs\.ph\/jobseekers\/job\//i.test(url);
  const schedule = String(job.schedule_fit || '').toLowerCase();
  const scheduleAllowed = ['fit', 'flexible', 'needs_confirmation'].includes(schedule);
  const route = String(job.application_route || '').toLowerCase();
  const appliesOnOlj = route === 'onlinejobs';
  const age = ageInDays(job.posted_or_updated_date || candidate.search_date);
  const fresh = age !== null && age >= -1 && age <= 7.99;

  if (!active || !direct || !scheduleAllowed || !appliesOnOlj || !fresh) continue;

  valid.push({
    json: {
      kind: 'verified_job',
      category: candidate.category,
      direct_link: url,
      title: job.title || candidate.search_title || '',
      employer: job.employer || candidate.search_employer || 'Not visible',
      posted_or_updated_date: job.posted_or_updated_date || candidate.search_date || '',
      work_type: job.work_type || candidate.search_work_type || '',
      required_hours_original: job.required_hours_original || '',
      required_hours_pht: job.required_hours_pht || (schedule === 'needs_confirmation' ? 'Needs confirmation' : ''),
      schedule_fit: schedule,
      salary: job.salary || candidate.search_salary || 'Not stated',
      main_requirements: Array.isArray(job.main_requirements) ? job.main_requirements : [],
      required_tools: Array.isArray(job.required_tools) ? job.required_tools : [],
      special_subject_keyword: job.special_subject_keyword || '',
      special_application_instructions: job.special_application_instructions || '',
      screening_questions: Array.isArray(job.screening_questions) ? job.screening_questions : [],
      posting_summary: job.posting_summary || candidate.search_snippet || '',
      verified_active: true,
      verified_at_pht: $now.setZone('Asia/Manila').toFormat('yyyy-MM-dd HH:mm'),
    },
  });
}

return valid.length ? valid : [{ json: { kind: 'none', reason: 'No newly posted, verified-active job passed the date, schedule, and application-route checks.' } }];

const state = $getWorkflowStaticData('global');
state.seenJobs = state.seenJobs || {};
const now = Date.now();
const keepMs = 90 * 24 * 60 * 60 * 1000;

for (const [url, record] of Object.entries(state.seenJobs)) {
  if (!record || now - Number(record.seenAt || 0) > keepMs) delete state.seenJobs[url];
}

const fresh = [];
for (const item of $input.all()) {
  const job = item.json;
  const url = String(job.direct_link || '').toLowerCase();
  const fingerprint = JSON.stringify({
    title: job.title,
    date: job.posted_or_updated_date,
    salary: job.salary,
    work_type: job.work_type,
    hours: job.required_hours_original,
  });
  if (state.seenJobs[url]?.fingerprint === fingerprint) continue;
  state.seenJobs[url] = { fingerprint, seenAt: now };
  fresh.push(item);
}

return fresh.length ? fresh : [{ json: { kind: 'none', reason: 'All suitable jobs were already reported and have no material update.' } }];
